#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long row[61] = {0};
    row[0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= i; ++j) {
            printf("%lld", row[j]);
            putchar(' ');
        }
        putchar('\n');
        for (int j = i + 1; j > 0; --j) {
            row[j] = row[j] + row[j - 1];
        }
    }
    return 0;
}
